const $=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);const fmt=(n,d)=>`${n<0?'−':''}${Math.abs(n)}/${d}`;const store={get(k){try{return localStorage.getItem('fondasi-operations-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-operations-'+k,v);return true}catch{return false}}};
const examples=[{a:1,b:2,c:1,d:4,op:1},{a:1,b:3,c:1,d:4,op:1},{a:5,b:6,c:1,d:4,op:-1},{a:3,b:4,c:2,d:3,op:1},{a:2,b:3,c:2,d:3,op:-1},{a:1,b:4,c:1,d:2,op:-1}];
function bar(target,n,d){target.replaceChildren();for(let i=0;i<d;i++){const p=document.createElement('span');p.className='piece'+(i<n?' filled':'');p.setAttribute('aria-hidden','true');target.append(p)}}
for(let n=-1;n<=2;n++){const x=210+180*n,line=document.createElementNS(ns,'line');for(const [k,v] of Object.entries({x1:x,x2:x,y1:58,y2:72,stroke:'#244d40'}))line.setAttribute(k,v);$('#ticks').append(line);const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',105);t.setAttribute('text-anchor','middle');t.textContent=String(n).replace('-','−');$('#ticks').append(t)}
function update(){const e=examples[Number($('#example').value)],common=e.b*e.d/gcd(e.b,e.d),a=e.a*common/e.b,c=e.c*common/e.d,result=a+e.op*c,partition=$('#partition').checked,symbol=e.op===1?'+':'−';for(const side of ['a','b']){const first=side==='a',n=partition?(first?a:c):(first?e.a:e.c),d=partition?common:(first?e.b:e.d);bar($('#bar-'+side),n,d);$('#bar-'+side).setAttribute('aria-label',`${n} per ${d}, dengan satu utuh yang sama`);$('#label-'+side).textContent=first?`Pecahan awal: ${fmt(e.a,e.b)}${partition?' = '+fmt(a,common):''}`:`${e.op===1?'Ditambahkan':'Dikurangkan'}: ${fmt(e.c,e.d)}${partition?' = '+fmt(c,common):''}`;}const base=`${fmt(e.a,e.b)} ${symbol} ${fmt(e.c,e.d)}`,g=gcd(result,common),simple=result===0?'0':common/g===1?String(result/g).replace('-','−'):fmt(result/g,common/g);$('#operation').textContent=partition?`${base} = ${fmt(a,common)} ${symbol} ${fmt(c,common)} = ${fmt(result,common)}${simple!==fmt(result,common)?' = '+simple:''}`:base+' = ?';$('#result-bars').replaceChildren();$('#result-bars').hidden=!partition||result<0;$('#result-caption').textContent='';if(partition&&result>=0){for(let row=0;row<2;row++){const b=document.createElement('div');b.className='single-bar';for(let j=0;j<common;j++){const i=row*common+j,p=document.createElement('span');p.className='piece';if(e.op===1){if(i<a)p.classList.add('filled');else if(i<result)p.classList.add('other')}else{if(i<result)p.classList.add('filled');else if(i<a)p.classList.add('removed')}b.append(p)}$('#result-bars').append(b)}$('#result-caption').textContent=e.op===1?'Hasil gabungan: hijau berasal dari pecahan awal, jingga dari pecahan yang ditambahkan. Setiap batang penuh bernilai 1.':'Hijau adalah bagian yang tersisa. Arsiran menunjukkan bagian yang dikurangkan. Setiap batang penuh bernilai 1.';$('#result-bars').setAttribute('aria-label',`Hasil ${result} per ${common}; ${e.op===1?'bagian digabungkan':'bagian yang dikurangkan ditandai arsiran'}`)}const x=210+180*result/common;$('#result-dot').setAttribute('cx',x);$('#result-distance').setAttribute('x2',x);$('#result-dot').style.visibility=partition?'visible':'hidden';$('#result-distance').style.visibility=partition?'visible':'hidden';$('#result-label').textContent=partition?simple:'';$('#result-label').setAttribute('x',Math.max(60,Math.min(540,x)));$('#visual-help').textContent=!partition?'Amati ukuran potongan pada kedua batang. Aktifkan pembagian ulang untuk melihat cara menghitungnya.':result<0?'Hasilnya negatif. Gunakan garis bilangan: mulai di 1/4, lalu bergerak 1/2 ke kiri sampai −1/4.':`Sekarang satu potongan berukuran 1/${common}. Kita ${e.op===1?'menggabungkan':'mengurangkan'} ${a} dan ${c} potongan.`;$('#feedback').textContent=!partition?'Panjang bagian berwarna harus tetap saat kita membagi ulang. Prediksikan hasilnya sebelum mengaktifkan pilihan di atas.':`${base} = ${simple}. `+(result===0?'Dua pecahan yang sama dikurangkan, sehingga tidak ada bagian yang tersisa.':result<0?'Hasil berada di kiri nol karena pecahan yang dikurangi lebih besar daripada pecahan awal.':result>common?`Ada ${Math.floor(result/common)} utuh dan ${result%common}/${common} lagi. Hasil penjumlahan pecahan boleh melebihi 1.`:'Hasil berada di antara 0 dan 1. Penyebut tetap karena ukuran potongan tidak berubah.');}$('#example').addEventListener('change',update);$('#partition').addEventListener('change',update);update();
$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=awal]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan terlebih dahulu.':v==='b'?'Tepat. 1/2 = 2/4. Dua seperempat ditambah satu seperempat menjadi tiga seperempat.':v==='a'?'Mari periksa ukurannya. 2/6 = 1/3 justru kurang dari setengah. Padahal menambah seperempat pada setengah harus memperbesar nilainya.':'Mulai dari gambar. Setengah dapat dibagi menjadi dua seperempat, kemudian digabung dengan satu seperempat lagi.'});
const qs=[{text:'2/7 + 3/7 = …',n:5,d:7,h:'Ukuran bagian sudah sama, yaitu sepertujuh.',why:'2 bagian sepertujuh ditambah 3 bagian sepertujuh menjadi 5/7.'},{text:'1/2 + 1/3 = …',n:5,d:6,h:'Gunakan penyebut 6. Setengah sama dengan 3/6.',why:'1/2 + 1/3 = 3/6 + 2/6 = 5/6.'},{text:'5/6 − 1/4 = …',n:7,d:12,h:'Ubah kedua pecahan menjadi bagian seperdua belas.',why:'5/6 − 1/4 = 10/12 − 3/12 = 7/12.'},{text:'3/4 + 3/4 = …',n:3,d:2,h:'Jumlahkan pembilangnya. Hasil boleh lebih dari satu.',why:'3/4 + 3/4 = 6/4 = 3/2, yaitu satu setengah.'},{text:'1/4 − 1/2 = …',n:-1,d:4,h:'Setengah sama dengan dua seperempat. Coba bayangkan gerakan ke kiri.',why:'1/4 − 2/4 = −1/4. Hasilnya negatif.'},{text:'2/3 − 2/3 = …',n:0,d:1,h:'Dua bilangan yang sama dikurangkan menghasilkan apa?',why:'2/3 − 2/3 = 0/3 = 0.'}];function parse(s){const m=s.trim().replace(/−/g,'-').match(/^([+-]?\d+)(?:\s*\/\s*([+-]?\d+))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]?Number(m[2]):1;if(!Number.isSafeInteger(n)||!Number.isSafeInteger(d)||d===0||Math.abs(n)>1000000||Math.abs(d)>1000000)return null;return{n,d}}const solved=new Set();$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.text}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}, pecahan atau bilangan bulat</label><div class="answer-line"><input class="fraction-answer" id="answer${i}" type="text" inputmode="text" placeholder="misalnya 3/4" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const i=Number(f.dataset.q),v=parse($('#answer'+i).value),q=qs[i],ok=v&&v.n*q.d===q.n*v.d;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=!v?'Tulis pecahan seperti -1/4 atau bilangan bulat seperti 0. Penyebut tidak boleh nol.':ok?'Tepat. '+q.why:'Belum tepat. Samakan ukuran bagian dahulu, lalu hitung kembali pembilangnya. Gunakan petunjuk bila perlu.';if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari ${qs.length} latihan telah dijawab dengan tepat.`}));$('#reflection').value=store.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=store.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum dapat disimpan. Salin jika ingin menyimpannya.'});function completed(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(store.get('complete')==='yes')completed();$('#complete').addEventListener('click',()=>{const saved=store.set('complete','yes');completed();$('#complete-note').textContent=saved?'Kemajuan tersimpan. Kamu bisa kembali berlatih kapan saja.':'Selesai. Kemajuan belum bisa disimpan di peramban ini.'});
